// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;

import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.junit.jupiter.api.Test;

class NativeExpressionDomainMetricsTest {

	private static final List<String> METRIC_NAMES = List.of("nativeRowTermDomainInputRowsActual",
			"nativeRowTermDomainEvaluationsActual", "nativeRowTermDomainHitsActual", "nativeRowTermDomainSpillsActual",
			"nativeRowTermDomainRefusalsActual", "nativeRowTermDomainUncachedActual",
			"nativeRowTermDomainLastTupleActual",
			"nativeRowTermDomainHashedActual", "nativeRowTermDomainIoReadsActual", "nativeRowTermDomainIoWritesActual",
			"nativeRowTermDomainIoReadBytesActual", "nativeRowTermDomainIoWriteBytesActual");

	@Test
	void initializesAllMetricsWithoutResettingExistingValues() {
		SingletonSet leaf = new SingletonSet();
		QueryRoot root = new QueryRoot(leaf);
		root.setRuntimeTelemetryEnabled(true);
		leaf.setRuntimeTelemetryEnabled(true);
		root.setLongMetricActual("nativeRowTermDomainHitsActual", 17);
		leaf.setLongMetricActual("nativeRowTermDomainHitsActual", 23);

		NativeExpressionDomain.initializeMetrics(root);
		assertThat(root.getLongMetricsActual()).containsOnlyKeys(METRIC_NAMES.toArray(String[]::new));
		assertThat(leaf.getLongMetricsActual()).containsOnlyKeys(METRIC_NAMES.toArray(String[]::new));
		for (String name : METRIC_NAMES) {
			assertThat(root.getLongMetricActual(name)).as("root metric %s", name)
					.isEqualTo(name.equals("nativeRowTermDomainHitsActual") ? 17 : 0);
			assertThat(leaf.getLongMetricActual(name)).as("leaf metric %s", name)
					.isEqualTo(name.equals("nativeRowTermDomainHitsActual") ? 23 : 0);
		}

		root.clearMetricsActual();
		leaf.clearMetricsActual();
		NativeExpressionDomain.initializeMetrics(root);
		for (String name : METRIC_NAMES) {
			assertThat(root.getLongMetricActual(name)).as("reset root metric %s", name).isZero();
			assertThat(leaf.getLongMetricActual(name)).as("reset leaf metric %s", name).isZero();
		}

		root.clearMetricsActual();
		leaf.clearMetricsActual();
		root.setRuntimeTelemetryEnabled(false);
		NativeExpressionDomain.initializeMetrics(root);
		assertThat(root.getLongMetricsActual()).isEmpty();
		assertThat(leaf.getLongMetricsActual()).isEmpty();
	}
}
